/* Puck uses NHL's public web API. Saved choices stay in this browser. */
const API = '/api/nhl';
const ESPN_NHL_NEWS = 'https://site.api.espn.com/apis/site/v2/sports/hockey/nhl/news';
const seasonStartYear = new Date().getMonth() < 7 ? new Date().getFullYear() - 1 : new Date().getFullYear();
const NHL_SEASON = `${seasonStartYear}${seasonStartYear + 1}`;
const NHL_SEASON_LABEL = `${String(seasonStartYear).slice(-2)}–${String(seasonStartYear + 1).slice(-2)}`;
const TEAM_LIST = [
  ['ANA','Anaheim Ducks'],['BOS','Boston Bruins'],['BUF','Buffalo Sabres'],['CAR','Carolina Hurricanes'],['CBJ','Columbus Blue Jackets'],['CGY','Calgary Flames'],['CHI','Chicago Blackhawks'],['COL','Colorado Avalanche'],['DAL','Dallas Stars'],['DET','Detroit Red Wings'],['EDM','Edmonton Oilers'],['FLA','Florida Panthers'],['LAK','Los Angeles Kings'],['MIN','Minnesota Wild'],['MTL','Montréal Canadiens'],['NJD','New Jersey Devils'],['NSH','Nashville Predators'],['NYI','New York Islanders'],['NYR','New York Rangers'],['OTT','Ottawa Senators'],['PHI','Philadelphia Flyers'],['PIT','Pittsburgh Penguins'],['SEA','Seattle Kraken'],['SJS','San Jose Sharks'],['STL','St. Louis Blues'],['TBL','Tampa Bay Lightning'],['TOR','Toronto Maple Leafs'],['UTA','Utah Mammoth'],['VAN','Vancouver Canucks'],['VGK','Vegas Golden Knights'],['WPG','Winnipeg Jets'],['WSH','Washington Capitals']
];
const DEFAULT_PLAYERS = [
  {id:8471214,name:'Alexander Ovechkin',team:'Washington Capitals',abbr:'WSH',pos:'LW'},
  {id:8474038,name:'Zemgus Girgensons',team:'Tampa Bay Lightning',abbr:'TBL',pos:'C'},
  {id:8477369,name:'Elvis Merzļikins',team:'Columbus Blue Jackets',abbr:'CBJ',pos:'G'},
  {id:8480180,name:'Teodors Bļugers',team:'Vancouver Canucks',abbr:'VAN',pos:'C'},
  {id:8481016,name:'Artūrs Šilovs',team:'Pittsburgh Penguins',abbr:'PIT',pos:'G'},
  {id:8482077,name:'Uvis Balinskis',team:'Florida Panthers',abbr:'FLA',pos:'D'},
  {id:8482120,name:'Rodrigo Ābols',team:'Philadelphia Flyers',abbr:'PHI',pos:'C'}
];
const fallbackNews = [
  {title:'The latest stories from around the National Hockey League',tag:'NHL.COM',url:'https://www.nhl.com/news',img:''},
  {title:'Watch the best moments and highlights from every game',tag:'VIDEO',url:'https://www.nhl.com/video',img:''},
  {title:'Follow the race toward the Stanley Cup Playoffs',tag:'STANDINGS',url:'https://www.nhl.com/standings',img:''}
];
const savedTeams = JSON.parse(localStorage.getItem('puckTeams') || 'null');
const savedPlayers = JSON.parse(localStorage.getItem('puckPlayers') || 'null');
let state = { teams: Array.isArray(savedTeams) && savedTeams.length ? savedTeams : ['WSH','TBL','VAN'], players: Array.isArray(savedPlayers) && savedPlayers.length ? savedPlayers : DEFAULT_PLAYERS.map(p=>p.id), standings:[], playersData:[] };
const $ = s => document.querySelector(s); const $$ = s => [...document.querySelectorAll(s)];
const logo = abbr => `https://assets.nhle.com/logos/nhl/svg/${abbr}_light.svg`;
const dateFmt = new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric'});
function teamName(abbr){ return TEAM_LIST.find(t=>t[0]===abbr)?.[1] || abbr; }
async function get(path){ const res=await fetch(`${API}${path}`); if(!res.ok) throw new Error(res.status); return res.json(); }
function escapeHtml(v=''){const d=document.createElement('div');d.textContent=v;return d.innerHTML;}
function showToast(msg){ const toast=$('#toast');toast.textContent=msg;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),2600); }
function setupDates(){ const d=new Date();$('#todayDay').textContent=d.toLocaleDateString('en-US',{weekday:'long'}).toUpperCase();$('#todayDate').textContent=dateFmt.format(d);$('#seasonLabel').textContent=`${NHL_SEASON_LABEL} Season`;$('#statsSeasonLabel').textContent=NHL_SEASON_LABEL; }
function switchView(view){ $$('.view').forEach(x=>x.classList.toggle('active',x.id===view)); $$('.nav-link').forEach(x=>x.classList.toggle('active',x.dataset.view===view));$('#breadcrumb').textContent=`MY NHL / ${view.toUpperCase()}`;$('.sidebar').classList.remove('open'); if(view==='settings') renderSettings(); }
function gameTeam(g,side){const t=side==='home'?g.homeTeam:g.awayTeam;return {abbr:t.abbrev||t.abbrev?.default||'NHL',score:t.score??'-',name:t.placeName?.default?`${t.placeName.default} ${t.commonName?.default||''}`:t.name?.default||t.abbrev};}
function gameCard(g){const away=gameTeam(g,'away'),home=gameTeam(g,'home'),isFinal=g.gameState==='FINAL'||g.gameState==='OFF';const winner=(t,o)=>isFinal&&Number(t.score)>Number(o.score);const gameType=Number(g.gameType),type=gameType===1?'PRESEASON':gameType===3?'PLAYOFFS':'REGULAR SEASON';const status=isFinal?`${type} · FINAL`:g.startTimeUTC?`${type} · ${new Date(g.startTimeUTC).toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}`:type;return `<button class="game-card" data-game-id="${g.id}"><span class="game-status ${isFinal?'final':''}">${status}</span><div class="game-teams"><div class="game-row ${winner(away,home)?'winner':''}"><img src="${logo(away.abbr)}" onerror="this.style.display='none'"/><span>${away.abbr}</span><strong class="score">${away.score}</strong></div><div class="game-row ${winner(home,away)?'winner':''}"><img src="${logo(home.abbr)}" onerror="this.style.display='none'"/><span>${home.abbr}</span><strong class="score">${home.score}</strong></div></div><span class="game-arrow">Details →</span></button>`;}
async function loadGames(){ const container=$('#scoreStrip');container.className='score-strip loading';container.innerHTML='<span class="loader"></span> Loading games…'; const results=await Promise.all(state.teams.map(async team=>{try{return {team,data:await get(`/club-schedule-season/${team}/now`)}}catch{return {team,data:null}}}));const available=results.filter(r=>r.data);const gameMap=new Map();available.flatMap(r=>r.data.games||[]).forEach(g=>gameMap.set(g.id,g));const now=Date.now();const games=[...gameMap.values()].filter(g=>[1,2,3].includes(Number(g.gameType))).sort((a,b)=>Math.abs(new Date(a.startTimeUTC)-now)-Math.abs(new Date(b.startTimeUTC)-now)).slice(0,6);container.className='score-strip';if(games.length){container.innerHTML=games.map(gameCard).join('');return;}container.innerHTML=available.length?'<div class="no-data">No scheduled games for these teams.</div>':'<div class="no-data"><strong>Live data needs the NHL app server.</strong><br>Run <code>npm start</code> in this NHL folder, then open <code>localhost:4173</code>.</div>';}
function articleFields(a){return {title:a.title?.default||a.headline?.default||a.title||'Latest NHL news',tag:a.type||a.category||'NHL.COM',url:a.url|| (a.urlPath?`https://www.nhl.com${a.urlPath}`:'https://www.nhl.com/news'),img:a.image?.url||a.image?.src||a.imageUrl||''};}
async function loadNews(){ try {const res=await fetch(ESPN_NHL_NEWS);if(!res.ok)throw new Error(res.status);const data=await res.json();const list=(data.articles||[]).slice(0,3).map(a=>({title:a.headline,tag:a.type==='HeadlineNews'?'BREAKING NEWS':'NHL NEWS',url:a.links?.web?.href||'https://www.espn.com/nhl/',img:a.images?.[0]?.url||''}));renderNews(list.length?list:fallbackNews);}catch{renderNews(fallbackNews);}}
function renderNews(list){$('#newsGrid').innerHTML=list.map((a,i)=>`<a class="news-card" href="${a.url}" target="_blank" rel="noreferrer" style="${a.img?`background-image:url('${a.img}')`:''}"><span class="news-card-tag">${escapeHtml(String(a.tag).toUpperCase())}</span><h3>${escapeHtml(a.title)}</h3><time>${i===0?'LATEST STORY':'NHL.COM'}</time></a>`).join('');}
async function loadPlayers(){const dest=$('#playersGrid');dest.innerHTML='<span class="loader"></span>';const selected=DEFAULT_PLAYERS.filter(p=>state.players.includes(p.id));if(!selected.length){dest.innerHTML='<div class="no-data">Your player watchlist is empty. Add players in Settings.</div>';$('#playerSummary').innerHTML='';return;}const results=await Promise.all(selected.map(async p=>{try{return {...p,detail:await get(`/player/${p.id}/landing`)}}catch{return {...p,detail:null}}}));state.playersData=results;const totalPts=results.reduce((x,p)=>x+(p.detail?.featuredStats?.regularSeason?.subSeason?.points||p.detail?.featuredStats?.regularSeason?.subSeason?.goals||0),0);$('#playerSummary').innerHTML=`<div class="summary-stat"><span>PLAYERS</span><strong>${results.length}</strong></div><div class="summary-stat"><span>COMBINED PTS</span><strong>${totalPts}</strong></div><div class="summary-stat"><span>LATVIAN PLAYERS</span><strong>${results.filter(p=>p.id!==8471214).length}</strong></div><div class="summary-stat"><span>WATCHLIST</span><strong>LIVE</strong></div>`;dest.innerHTML=results.map(renderPlayer).join('');}
function renderPlayer(p){const d=p.detail||{},stats=d.featuredStats?.regularSeason?.subSeason||d.featuredStats?.regularSeason||{};const goalie=p.pos==='G';const head=d.headshot||`https://assets.nhle.com/mugs/nhl/${NHL_SEASON}/${p.abbr}/${p.id}.png`;return `<article class="player-card" style="--player-color:${p.id===8471214?'#f4d86a':'#cce4ee'}"><div class="player-top"><span class="player-team">${p.abbr}</span><img class="player-headshot" src="${head}" alt="" onerror="this.style.display='none'" /></div><h3>${escapeHtml(p.name)}</h3><span class="position">${p.pos} · ${escapeHtml(d.currentTeamAbbrev||p.team)}</span><div class="player-stats">${goalie?`<div><span>WINS</span><strong>${stats.wins??'—'}</strong></div><div><span>SV%</span><strong>${stats.savePctg?Number(stats.savePctg).toFixed(3):'—'}</strong></div><div><span>GAA</span><strong>${stats.goalsAgainstAvg??'—'}</strong></div>`:`<div><span>GOALS</span><strong>${stats.goals??'—'}</strong></div><div><span>ASSISTS</span><strong>${stats.assists??'—'}</strong></div><div><span>POINTS</span><strong>${stats.points??'—'}</strong></div>`}</div></article>`;}
async function loadStandings(){const dest=$('#standingsContent');dest.innerHTML='<span class="loader"></span> Loading standings…';try{const data=await get('/standings/now');state.standings=data.standings||[];renderStandings('Eastern');}catch{dest.innerHTML='<div class="no-data">Could not load live standings. Try refreshing.</div>';}}
function renderStandings(conference){const divisions=conference==='Eastern'?['Atlantic','Metropolitan']:['Central','Pacific'];const icon=t=>t.teamLogo||logo(t.teamAbbrev?.default||t.teamAbbrev);$('#standingsContent').innerHTML=`<div class="division-grid">${divisions.map(div=>{const rows=state.standings.filter(t=>(t.divisionName||t.divisionName?.default)===div).sort((a,b)=>(a.divisionSequence||99)-(b.divisionSequence||99));return `<article class="division"><div class="division-title"><h2>${div} Division</h2><span>GP / W / L / PTS</span></div><table class="standings-table"><thead><tr><th>#</th><th>TEAM</th><th>GP</th><th>W</th><th>L</th><th>PTS</th></tr></thead><tbody>${rows.map((t,i)=>`<tr><td class="rank">${t.divisionSequence||i+1}</td><td><img class="team-mini" src="${icon(t)}" onerror="this.style.display='none'"/>${escapeHtml(t.teamAbbrev?.default||t.teamAbbrev||'')}</td><td>${t.gamesPlayed}</td><td>${t.wins}</td><td>${t.losses}</td><td class="standing-points">${t.points}</td></tr>`).join('')}</tbody></table></article>`;}).join('')}</div>`;}
async function showGame(id){const modal=$('#gameModal'),content=$('#modalContent');modal.classList.add('open');modal.setAttribute('aria-hidden','false');content.innerHTML='<div class="modal-body"><span class="loader"></span> Loading game details…</div>';try{const [box,landing]=await Promise.all([get(`/gamecenter/${id}/boxscore`),get(`/gamecenter/${id}/landing`).catch(()=>({}))]);const away={abbr:box.awayTeam.abbrev,score:box.awayTeam.score,name:box.awayTeam.placeName?.default||box.awayTeam.name?.default||box.awayTeam.abbrev};const home={abbr:box.homeTeam.abbrev,score:box.homeTeam.score,name:box.homeTeam.placeName?.default||box.homeTeam.name?.default||box.homeTeam.abbrev};const goals=(landing.summary?.scoring||[]).flatMap(p=>p.goals||[]);const roster=[...(box.playerByGameStats?.awayTeam?.forwards||[]),...(box.playerByGameStats?.homeTeam?.forwards||[])].slice(0,12);content.innerHTML=`<div class="modal-hero"><span class="modal-status">${escapeHtml(box.gameState||'GAME DETAILS')} · ${box.gameDate||''}</span><div class="modal-teams"><div class="modal-team"><img src="${logo(away.abbr)}"/>${escapeHtml(away.name)}</div><strong class="modal-score">${away.score} – ${home.score}</strong><div class="modal-team"><img src="${logo(home.abbr)}"/>${escapeHtml(home.name)}</div></div></div><div class="modal-body"><div class="detail-grid"><div><h2>Scoring summary</h2><ul class="detail-list">${goals.length?goals.map(g=>`<li><small>${g.periodDescriptor?.number||g.period||''} · ${g.timeInPeriod||''}</small><span><strong>${escapeHtml(g.firstName?.default||'')} ${escapeHtml(g.lastName?.default||g.name?.default||'')}</strong><br>${escapeHtml(g.teamAbbrev?.default||'')} · ${escapeHtml(g.goalModifier||'Goal')}</span></li>`).join(''):'<li>Scoring details will appear after the game begins.</li>'}</ul></div><div><h2>Game roster</h2><ul class="detail-list">${roster.length?roster.map(p=>`<li><small>#${p.sweaterNumber||'—'}</small><span><strong>${escapeHtml(p.name?.default||`${p.firstName?.default||''} ${p.lastName?.default||''}`)}</strong><br>${escapeHtml(p.position||'')}</span></li>`).join(''):'<li>Rosters are not yet available.</li>'}</ul></div></div><a class="highlights" target="_blank" rel="noreferrer" href="https://www.nhl.com/gamecenter/${id}">Watch highlights on NHL.com ↗</a></div>`;}catch{content.innerHTML='<div class="modal-body"><h2>Game details unavailable</h2><p class="subtle">Please try again in a moment.</p></div>';}}
function renderSettings(){ $('#teamChecks').innerHTML=TEAM_LIST.map(([id,name])=>`<label class="check-item"><input type="checkbox" value="${id}" ${state.teams.includes(id)?'checked':''}/><img class="check-logo" src="${logo(id)}" onerror="this.style.display='none'"/><span>${escapeHtml(name)}</span></label>`).join('');$('#playerChecks').innerHTML=DEFAULT_PLAYERS.map(p=>`<label class="check-item"><input type="checkbox" value="${p.id}" ${state.players.includes(p.id)?'checked':''}/><span><strong>${escapeHtml(p.name)}</strong><br><span class="check-sub">${p.abbr} · ${p.pos}</span></span></label>`).join('');updateSettingsCount();$$('#settings input').forEach(i=>i.addEventListener('change',updateSettingsCount)); }
function updateSettingsCount(){$('#teamCount').textContent=`${$$('#teamChecks input:checked').length} selected`;$('#playerCount').textContent=`${$$('#playerChecks input:checked').length} selected`;}
function saveSettings(){state.teams=$$('#teamChecks input:checked').map(x=>x.value);state.players=$$('#playerChecks input:checked').map(x=>Number(x.value));localStorage.setItem('puckTeams',JSON.stringify(state.teams));localStorage.setItem('puckPlayers',JSON.stringify(state.players));loadGames();loadPlayers();showToast('Your Puck dashboard has been updated.');}
async function refresh(){ $('#syncStatus').textContent='● Refreshing live data…';await Promise.all([loadGames(),loadNews(),loadPlayers(),loadStandings()]);$('#syncStatus').textContent='● Updated just now';showToast('Live NHL data refreshed.');}
function bind(){ $$('.nav-link,.settings-trigger,.mobile-settings').forEach(b=>b.addEventListener('click',()=>switchView(b.dataset.view)));$('#menuButton').addEventListener('click',()=>$('.sidebar').classList.toggle('open'));$('#refreshButton').addEventListener('click',refresh);$('#saveSettings').addEventListener('click',saveSettings);$('#scoreStrip').addEventListener('click',e=>{const card=e.target.closest('[data-game-id]');if(card)showGame(card.dataset.gameId);});$('.modal-close').addEventListener('click',()=>$('#gameModal').classList.remove('open'));$('#gameModal').addEventListener('click',e=>{if(e.target.id==='gameModal')$('#gameModal').classList.remove('open')});$$('.standings-tab').forEach(b=>b.addEventListener('click',()=>{$$('.standings-tab').forEach(x=>x.classList.toggle('active',x===b));renderStandings(b.dataset.conference)}));}
setupDates();bind();refresh();setInterval(refresh,300000);
